            locale?: "uz-Latn" | "uz-Cyrl" | "ru" | "en";
            home_city_id?: number;
            /** Format: date */
            birth_date?: string;
            /** @enum {string} */
            gender?: "male" | "female" | "other" | "undisclosed";
